//! Parent-owned measured linker service. No compiler-supplied flags, tool paths,
//! SDK paths, response files or auto-link load commands enter a tool process.
use crate::{filesystem_channel::{Operation,Request},native_artifact_channel as channel,native_target::Target,macos_filesystem_session::{self as filesystem,Grant},macos_snapshot::Image,macos_supervisor::{Host,Limits,LinkerPaths},macos_seatbelt::Role,unix_filesystem::Broker};
use serde::Deserialize;use sha2::{Digest,Sha256};
use std::{collections::BTreeMap,fs::{self,File,OpenOptions},io::{self,Read,Write},os::{fd::AsRawFd,unix::fs::{DirBuilderExt,FileExt,MetadataExt,OpenOptionsExt,PermissionsExt}},path::{Path,PathBuf},sync::atomic::{AtomicBool,Ordering}};
fn invalid(message:&'static str)->io::Error{io::Error::new(io::ErrorKind::InvalidInput,message)}
fn hash(bytes:&[u8])->String{format!("sha256:{:x}",Sha256::digest(bytes))}
#[derive(Deserialize)]#[serde(deny_unknown_fields)]struct Tool{path:PathBuf,sha256:String}
#[derive(Deserialize)]#[serde(deny_unknown_fields)]struct SdkEntry{path:String,kind:String,#[serde(default)]size:u64,#[serde(default)]sha256:String,#[serde(default)]target:String}
#[derive(Deserialize)]#[serde(deny_unknown_fields)]struct Configuration{schema:String,profile:String,identity:String,sdk:PathBuf,tools:PathBuf,#[serde(rename="sdkVersion")]sdk_version:String,#[serde(default,rename="linkerDriver")]driver:Option<String>,linker:Tool,runtime:Vec<Tool>,#[serde(rename="sdkFiles")]sdk_files:Vec<SdkEntry>}
type Identity=(u64,u64,u64,i64,i64,i64,i64,u32);
fn identity(m:&fs::Metadata)->Identity{(m.dev(),m.ino(),m.len(),m.mtime(),m.mtime_nsec(),m.ctime(),m.ctime_nsec(),m.mode())}
fn trusted(m:&fs::Metadata)->io::Result<()>{let owner=m.uid()==0||m.uid()==unsafe{libc::geteuid()};let mask=if m.uid()==0{0o022}else{0o222};if !owner||!m.is_symlink()&&m.mode()&mask!=0{return Err(invalid("measured SDK inputs require OS ownership or a sealed read-only owner copy"));}Ok(())}
fn directory(path:&Path)->io::Result<File>{if !path.is_absolute()||path.parent().is_none()||fs::canonicalize(path)?!=path{return Err(invalid("canonical measured directory required"));}let file=OpenOptions::new().read(true).custom_flags(libc::O_DIRECTORY|libc::O_NOFOLLOW|libc::O_CLOEXEC).open(path)?;trusted(&file.metadata()?)?;Ok(file)}
struct Pinned{path:PathBuf,file:File,identity:Identity}
impl Pinned{
 fn new(path:&Path,expected:&str)->io::Result<Self>{if !path.is_absolute()||fs::canonicalize(path)?!=path{return Err(invalid("canonical measured file required"));}let file=OpenOptions::new().read(true).custom_flags(libc::O_NOFOLLOW|libc::O_CLOEXEC|libc::O_NONBLOCK).open(path)?;let metadata=file.metadata()?;trusted(&metadata)?;if !metadata.is_file()||metadata.len()>8u64<<30{return Err(invalid("invalid measured tool input"));}let before=identity(&metadata);let mut sha=Sha256::new();let mut reader=&file;let mut bytes=[0;1<<16];loop{let n=reader.read(&mut bytes)?;if n==0{break;}sha.update(&bytes[..n]);}if format!("sha256:{:x}",sha.finalize())!=expected||identity(&file.metadata()?)!=before{return Err(invalid("measured tool input changed"));}let item=Self{path:path.into(),file,identity:before};item.verify()?;Ok(item)}
 fn verify(&self)->io::Result<()>{let named=fs::symlink_metadata(&self.path)?;trusted(&named)?;if !named.is_file()||identity(&named)!=self.identity||identity(&self.file.metadata()?)!=self.identity{return Err(invalid("measured tool input identity changed"));}Ok(())}
}
pub struct Linker{pub identity:String,configuration:Configuration,tool:Vec<u8>,inputs:Vec<Pinned>,sdk_root:File,tools_root:File,sdk_state:BTreeMap<String,Identity>,tools_state:BTreeMap<String,Identity>}
fn sdk_state(root:&Path)->io::Result<BTreeMap<String,Identity>>{
 fn walk(root:&Path,folder:&Path,state:&mut BTreeMap<String,Identity>)->io::Result<()>{for entry in fs::read_dir(folder)?{let entry=entry?;let path=entry.path();let relative=path.strip_prefix(root).map_err(|_|invalid("SDK path escaped root"))?.to_str().ok_or_else(||invalid("Unicode SDK path required"))?.to_string();crate::macos_format::validate_sdk_relative(&relative)?;if state.len()>=200000{return Err(invalid("SDK inventory exceeds bound"));}let metadata=fs::symlink_metadata(&path)?;trusted(&metadata)?;if !metadata.is_file()&&!metadata.is_dir()&&!metadata.is_symlink(){return Err(invalid("unsupported SDK entry"));}state.insert(relative,identity(&metadata));if metadata.is_symlink(){if !fs::canonicalize(&path)?.starts_with(root){return Err(invalid("SDK symlink escapes root"));}}else if metadata.is_dir(){walk(root,&path,state)?;}}Ok(())}
 let mut state=BTreeMap::new();walk(root,root,&mut state)?;Ok(state)
}
impl Linker{
 pub fn from_file(path:&Path)->io::Result<Self>{
  let mut bytes=vec![];File::open(path)?.take((64<<20)+1).read_to_end(&mut bytes)?;Self::load(&bytes,None)
 }
 pub fn from_package(bytes:&[u8],root:&Path)->io::Result<Self>{Self::load(bytes,Some(root))}
 fn load(bytes:&[u8],package:Option<&Path>)->io::Result<Self>{
  if bytes.len()>64<<20{return Err(invalid("linker configuration exceeds bound"));}let mut value:serde_json::Value=serde_json::from_slice(bytes)?;let mut configuration:Configuration=serde_json::from_value(value.clone())?;value.as_object_mut().ok_or_else(||invalid("linker object required"))?.remove("identity");
  if configuration.schema!=if package.is_some(){"kelft-macos-linker-installed/1"}else{"kelft-macos-linker-development/1"}||configuration.profile!=Target::current()?.id()||configuration.identity!=hash(&serde_json::to_vec(&value)?)||configuration.runtime.len()>64||configuration.sdk_files.is_empty()||configuration.sdk_files.len()>200000||!version(&configuration.sdk_version){return Err(invalid("linker identity, profile or inventory differs"));}
  let lld=configuration.driver.as_deref()==Some("lld-macho/1");if configuration.driver.is_some()&&(!lld||package.is_none()){return Err(invalid("unsupported measured linker driver"));}
  if let Some(root)=package{
   if !root.is_absolute()||fs::canonicalize(root)?!=root{return Err(invalid("canonical package root required"));}
   let resolve=|path:&Path,name:&str|->io::Result<PathBuf>{if path.to_str()!=Some(name){return Err(invalid("installed toolchain path differs from fixed layout"));}Ok(root.join(name))};
   configuration.sdk=resolve(&configuration.sdk,"rootfs/toolchain/sdk")?;configuration.tools=resolve(&configuration.tools,"rootfs/toolchain/usr")?;configuration.linker.path=resolve(&configuration.linker.path,"rootfs/toolchain/usr/bin/ld")?;
   for input in &mut configuration.runtime{if !input.path.is_absolute(){let text=input.path.to_str().ok_or_else(||invalid("Unicode runtime path required"))?;crate::filesystem_channel::validate_relative(text)?;if !text.starts_with("rootfs/toolchain/usr/lib/"){return Err(invalid("installed runtime layout differs"));}input.path=root.join(text);}else if !input.path.starts_with("/usr/lib")&&!input.path.starts_with("/System"){return Err(invalid("installed runtime escapes native system roots"));}}
  }
  let sdk_root=directory(&configuration.sdk)?;let tools_root=directory(&configuration.tools)?;if !configuration.linker.path.starts_with(configuration.tools.join("bin")){return Err(invalid("linker is outside measured tools"));}
  let mut inputs=vec![Pinned::new(&configuration.linker.path,&configuration.linker.sha256)?];for tool in &configuration.runtime{if !tool.path.starts_with(&configuration.tools)&&!tool.path.starts_with("/usr/lib")&&!tool.path.starts_with("/System"){return Err(invalid("runtime input escapes measured roots"));}inputs.push(Pinned::new(&tool.path,&tool.sha256)?);}
  let tool_maximum=if lld{128<<20}else{64<<20};if inputs[0].identity.2>tool_maximum{return Err(invalid("measured linker exceeds tool bound"));}let mut tool=vec![0;inputs[0].identity.2 as usize];inputs[0].file.read_exact_at(&mut tool,0)?;inputs[0].verify()?;if hash(&tool)!=configuration.linker.sha256{return Err(invalid("linker bytes changed"));}crate::macos_format::validate_tool_bounded(&tool,Target::current()?,tool_maximum as usize)?;
  let tools_state=sdk_state(&configuration.tools)?;
  let measured_tools=std::iter::once(&configuration.linker).chain(configuration.runtime.iter()).filter(|input|input.path.starts_with(&configuration.tools)).map(|input|input.path.strip_prefix(&configuration.tools).unwrap().to_str().unwrap().to_owned()).collect::<std::collections::HashSet<_>>();
  for name in tools_state.keys(){let m=fs::symlink_metadata(configuration.tools.join(name))?;if !m.is_dir()&&(!m.is_file()||!measured_tools.contains(name)){return Err(invalid("tool directory contains unmeasured input"));}}
  let state=sdk_state(&configuration.sdk)?;let mut inventoried=std::collections::HashSet::new();
  for entry in &configuration.sdk_files{crate::macos_format::validate_sdk_relative(&entry.path)?;if !inventoried.insert(entry.path.clone()){return Err(invalid("duplicate SDK input"));}let path=configuration.sdk.join(&entry.path);let metadata=fs::symlink_metadata(&path)?;
   if entry.kind=="file"{if !metadata.is_file()||metadata.len()!=entry.size{return Err(invalid("SDK file changed"));}let pin=Pinned::new(&path,&entry.sha256)?;drop(pin);}
   else if entry.kind=="symlink"{if !metadata.is_symlink()||fs::canonicalize(&path)?!=configuration.sdk.join(&entry.target){return Err(invalid("SDK link changed"));}}
   else{return Err(invalid("unsupported SDK inventory kind"));}
  }
  for(name,_)in &state{if !fs::symlink_metadata(configuration.sdk.join(name))?.is_dir()&&!inventoried.contains(name){return Err(invalid("SDK contains unmeasured input"));}}
  let identity=configuration.identity.clone();let result=Self{identity,configuration,tool,inputs,sdk_root,tools_root,sdk_state:state,tools_state};result.verify()?;Ok(result)
 }
 pub fn protected(&self)->[&Path;2]{[&self.configuration.sdk,&self.configuration.tools]}
 fn verify(&self)->io::Result<()>{for (path,file)in [(&self.configuration.sdk,&self.sdk_root),(&self.configuration.tools,&self.tools_root)]{if identity(&fs::symlink_metadata(path)?)!=identity(&file.metadata()?){return Err(invalid("measured tool directory changed"));}}for input in &self.inputs{input.verify()?;}if sdk_state(&self.configuration.tools)?!=self.tools_state{return Err(invalid("measured tool tree changed"));}if sdk_state(&self.configuration.sdk)?!=self.sdk_state{return Err(invalid("measured SDK changed"));}Ok(())}
 pub fn execute(&self,host:&Host,base:&Path,request:&channel::Request,authority:&[Grant],private:&[PathBuf],cancel:&AtomicBool)->io::Result<channel::Response>{
  let reject=|status|Ok(channel::Response{status,stdout:vec![],stderr:vec![]});if request.target!=format!("linker-{}-v1",Target::current()?.id()){return reject(-1);}
  if request.args.len()!=2||request.args[1]!=self.identity||!request.read.is_empty()||request.write!=[request.args[0].clone()]{return reject(-2);}
  let destination=match filesystem::mapped_path(&request.args[0],true,authority){Ok(path)=>path,Err(_)=>return reject(-2)};
  for root in private.iter().map(PathBuf::as_path).chain(self.protected()).chain([host.directory()]){if destination.starts_with(root)||root.starts_with(&destination){return reject(-2);}}
  if crate::macos_format::validate_object(&request.image,Target::current()?).is_err(){return reject(-4);}self.verify()?;
  let mut broker=Broker::default();let output_root=broker.add_root(&destination,false,true)?;
  let lld=self.configuration.driver.as_deref()==Some("lld-macho/1");let image=if lld{Image::linker_tool(&self.tool,&self.configuration.linker.sha256,base)?}else{Image::tool(&self.tool,&self.configuration.linker.sha256,base)?};let work=Work::new(image.directory(),&request.image)?;
  let mut results=vec![];
  for signed in [false,true]{if cancel.load(Ordering::Acquire){return reject(-3);}let output=work.output.join(if signed{"image"}else{"unsigned"});
   let mut args:Vec<String>=["-arch",if Target::current()?==Target::MacosX64{"x86_64"}else{"arm64"},"-platform_version","macos","14.0",&self.configuration.sdk_version,"-syslibroot",self.configuration.sdk.to_str().ok_or_else(||invalid("Unicode SDK path required"))?,"-lSystem","-no_uuid","-e","_k_start",if signed{"-adhoc_codesign"}else{"-no_adhoc_codesign"}].into_iter().map(str::to_owned).collect();if lld{args.splice(0..0,["-flavor".into(),"darwin".into()]);}else{args.extend(["-stack_size".into(),"0x1000000".into()]);}args.extend([work.object.to_str().unwrap().into(),"-o".into(),output.to_str().unwrap().into()]);
   let env=[("DYLD_LIBRARY_PATH".into(),self.configuration.tools.join("lib").to_str().ok_or_else(||invalid("Unicode library path required"))?.into())];
   let execution=host.run(&image,Role::Linker,&args,&env,&[],Some(LinkerPaths{sdk:self.configuration.sdk.clone(),tools:self.configuration.tools.clone(),object:work.object.clone(),output:work.output.clone()}),Limits{wall_ms:600000,output_bytes:1<<20},Some(cancel))?;
   self.verify()?;work.verify()?;if let Some(failure)=execution.failure{return Err(io::Error::other(format!("measured linker execution failed: {failure}: {}{}",String::from_utf8_lossy(&execution.stdout),String::from_utf8_lossy(&execution.stderr))));}
   if execution.exit!=Some(0){return Ok(channel::Response{status:execution.exit.unwrap_or(125),stdout:execution.stdout,stderr:execution.stderr});}if !execution.stdout.is_empty()||!execution.stderr.is_empty(){return Err(invalid("unexpected trusted linker output"));}
   let mut bytes=work.read(&output)?;if lld{crate::macos_linked_image::seal_stack(&mut bytes,Target::current()?)?;}crate::macos_snapshot::validate(&bytes)?;if signature_present(&bytes)?!=signed{return Err(invalid("linked image signing state differs"));}results.push(bytes);
  }
  if cancel.load(Ordering::Acquire){return reject(-3);}let signed=results.pop().unwrap();let unsigned=results.pop().unwrap();let mut sequence=1;let mut operation=|op,handle,path:&str,data:Vec<u8>|{let request=Request{sequence,operation:op,handle,path:path.into(),amount:data.len() as u32,data};sequence+=1;broker.execute(&request)};
  let(token,_)=operation(Operation::OpenWrite,output_root,".",vec![])?;for chunk in signed.chunks(65536){operation(Operation::Write,token,"",chunk.to_vec())?;}drop(operation);broker.executable(token)?;broker.execute(&Request{sequence,operation:Operation::Close,handle:token,path:String::new(),amount:0,data:vec![]})?;
  Ok(channel::Response{status:0,stdout:serde_json::to_vec(&serde_json::json!({"schema":"kelft-macos-link-result/1","unsignedSHA256":hash(&unsigned),"signedSHA256":hash(&signed),"signing":"measured-ld-adhoc","toolchainIdentity":self.identity,"certified":false}))?,stderr:vec![]})
 }
}
fn version(text:&str)->bool{let parts:Vec<_>=text.split('.').collect();!parts.is_empty()&&parts.len()<=3&&parts.iter().enumerate().all(|(index,part)|!part.is_empty()&&part.bytes().all(|b|b.is_ascii_digit())&&part.parse::<u32>().is_ok_and(|n|if index==0{(14..=65535).contains(&n)}else{n<=255}))}
fn signature_present(bytes:&[u8])->io::Result<bool>{let mut at=32;let count=u32::from_le_bytes(bytes[16..20].try_into().unwrap());let mut found=false;for _ in 0..count{let command=u32::from_le_bytes(bytes[at..at+4].try_into().unwrap());let size=u32::from_le_bytes(bytes[at+4..at+8].try_into().unwrap()) as usize;if command==0x1d{if found||size!=16{return Err(invalid("invalid signing command"));}let offset=u32::from_le_bytes(bytes[at+8..at+12].try_into().unwrap()) as usize;let length=u32::from_le_bytes(bytes[at+12..at+16].try_into().unwrap()) as usize;if length<12||offset.checked_add(length)!=Some(bytes.len())||bytes[offset..offset+4]!=[0xfa,0xde,0x0c,0xc0]{return Err(invalid("invalid ad-hoc signature extent"));}found=true;}at+=size;}Ok(found)}
struct Work{root:File,output_root:File,object_file:File,object:PathBuf,output:PathBuf,object_hash:String,root_id:Identity,output_id:Identity}
impl Work{
 fn new(root:&Path,object:&[u8])->io::Result<Self>{let directory=OpenOptions::new().read(true).custom_flags(libc::O_DIRECTORY|libc::O_NOFOLLOW|libc::O_CLOEXEC).open(root)?;let object_path=root.join("input.o");let mut object_file=OpenOptions::new().read(true).write(true).create_new(true).mode(0o600).custom_flags(libc::O_NOFOLLOW|libc::O_CLOEXEC).open(&object_path)?;object_file.write_all(object)?;object_file.sync_all()?;object_file.set_permissions(fs::Permissions::from_mode(0o400))?;let output=root.join("output");fs::DirBuilder::new().mode(0o700).create(&output)?;let output_root=OpenOptions::new().read(true).custom_flags(libc::O_DIRECTORY|libc::O_NOFOLLOW|libc::O_CLOEXEC).open(&output)?;let result=Self{root_id:identity(&directory.metadata()?),output_id:identity(&output_root.metadata()?),root:directory,output_root,object_file,object:object_path,output,object_hash:hash(object)};Ok(result)}
 fn verify(&self)->io::Result<()>{for(file,path,id)in [(&self.root,self.object.parent().unwrap(),self.root_id),(&self.output_root,self.output.as_path(),self.output_id)]{let named=fs::symlink_metadata(path)?;let held=file.metadata()?;if !named.is_dir()||named.dev()!=id.0||named.ino()!=id.1||held.dev()!=id.0||held.ino()!=id.1||held.mode()&0o7777!=0o700{return Err(invalid("private linker directory changed"));}}let named=fs::symlink_metadata(&self.object)?;let held=self.object_file.metadata()?;if !named.is_file()||identity(&named)!=identity(&held)||held.nlink()!=1||held.mode()&0o7777!=0o400||hash(&fs::read(&self.object)?)!=self.object_hash{return Err(invalid("private linker object changed"));}Ok(())}
 fn read(&self,path:&Path)->io::Result<Vec<u8>>{let mut file=OpenOptions::new().read(true).custom_flags(libc::O_NOFOLLOW|libc::O_CLOEXEC|libc::O_NONBLOCK).open(path)?;let m=file.metadata()?;if !m.is_file()||m.nlink()!=1||m.dev()!=self.output_id.0||m.uid()!=unsafe{libc::geteuid()}||m.len()>64<<20{return Err(invalid("invalid private linker output"));}let mut bytes=vec![];Read::by_ref(&mut file).take((64<<20)+1).read_to_end(&mut bytes)?;if identity(&m)!=identity(&file.metadata()?){return Err(invalid("linked image changed while reading"));}Ok(bytes)}
}
impl Drop for Work{fn drop(&mut self){unsafe{libc::unlinkat(self.output_root.as_raw_fd(),c"image".as_ptr(),0);libc::unlinkat(self.output_root.as_raw_fd(),c"unsigned".as_ptr(),0);libc::unlinkat(self.root.as_raw_fd(),c"input.o".as_ptr(),0);libc::unlinkat(self.root.as_raw_fd(),c"output".as_ptr(),libc::AT_REMOVEDIR);}}}
#[cfg(test)]mod tests{
 use super::*;
 struct Tree(PathBuf);
 impl Drop for Tree{fn drop(&mut self){fn writable(path:&Path){let Ok(m)=fs::symlink_metadata(path)else{return;};if m.is_dir(){let _=fs::set_permissions(path,fs::Permissions::from_mode(0o700));if let Ok(entries)=fs::read_dir(path){for entry in entries.flatten(){writable(&entry.path());}}}}writable(&self.0);let _=fs::remove_dir_all(&self.0);}}
 #[test]fn measured_tools_reject_unlisted_libraries_and_nested_replacement(){
  let mut nonce=[0;24];getrandom::fill(&mut nonce).unwrap();let root=fs::canonicalize(std::env::temp_dir()).unwrap().join(format!("kelft-linker-test-{}",hash(&nonce).trim_start_matches("sha256:")));fs::create_dir(&root).unwrap();let _cleanup=Tree(root.clone());
  let sdk=root.join("sdk");let tools=root.join("usr");fs::create_dir(&sdk).unwrap();fs::create_dir(&tools).unwrap();fs::create_dir(tools.join("bin")).unwrap();fs::create_dir(tools.join("lib")).unwrap();
  let tool=fs::read(std::env::current_exe().unwrap()).unwrap();let executable=tools.join("bin/ld");fs::write(&executable,&tool).unwrap();fs::set_permissions(&executable,fs::Permissions::from_mode(0o555)).unwrap();fs::write(sdk.join("APR::Base64.3pm"),b"sdk").unwrap();fs::set_permissions(sdk.join("APR::Base64.3pm"),fs::Permissions::from_mode(0o444)).unwrap();
  for directory in [&sdk,&tools,&tools.join("bin"),&tools.join("lib")]{fs::set_permissions(directory,fs::Permissions::from_mode(0o555)).unwrap();}
  let mut value=serde_json::json!({"schema":"kelft-macos-linker-development/1","profile":Target::current().unwrap().id(),"sdk":sdk,"tools":tools,"sdkVersion":"14.0","linker":{"path":executable,"sha256":hash(&tool)},"runtime":[],"sdkFiles":[{"path":"APR::Base64.3pm","kind":"file","size":3,"sha256":hash(b"sdk")}]});let expected=hash(&serde_json::to_vec(&value).unwrap());value["identity"]=expected.into();let bytes=serde_json::to_vec(&value).unwrap();let linker=Linker::load(&bytes,None).unwrap();linker.verify().unwrap();
  fs::set_permissions(tools.join("lib"),fs::Permissions::from_mode(0o755)).unwrap();fs::write(tools.join("lib/unlisted.dylib"),b"unmeasured library").unwrap();fs::set_permissions(tools.join("lib/unlisted.dylib"),fs::Permissions::from_mode(0o444)).unwrap();fs::set_permissions(tools.join("lib"),fs::Permissions::from_mode(0o555)).unwrap();assert!(linker.verify().is_err());let error=Linker::load(&bytes,None).err().expect("unlisted tool library accepted");assert!(error.to_string().contains("unmeasured input"));
 }
}
